#!/usr/bin/env python3
"""Genera le mappe di traduzione map-<lang>.json per il journal.

Le traduzioni sono indicizzate sull'elenco dei segmenti unici "sostanziali"
(> 4 parole, non URL) estratti da segments.json, nello stesso ordine
deterministico. None = il segmento resta in originale (didascalie, nomi).
"""
import json
import os

BASE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
DIR = os.path.join(BASE, "src", "data", "journal-i18n")

segments = json.load(open(os.path.join(DIR, "segments.json")))

# stesso ordine dell'estrazione: segmenti unici sostanziali
uniq = []
seen = set()
for slug, data in segments.items():
    for s in data["segments"]:
        t = s.strip()
        if t and t not in seen and len(t.split()) > 4 and not t.startswith("http"):
            seen.add(t)
            uniq.append(t)

