ALL = {"en": EN, "de": DE, "fr": FR, "es": ES}

for lang, arr in ALL.items():
    if len(arr) != len(uniq):
        raise SystemExit(f"[{lang}] {len(arr)} traduzioni per {len(uniq)} segmenti: allineare!")
    seg_map = {}
    for orig, trans in zip(uniq, arr):
        seg_map[orig] = trans if trans is not None else orig
    seg_map.update(SHORT[lang])
    with open(os.path.join(DIR, f"map-{lang}.json"), "w") as f:
        json.dump({"titles": TITLES[lang], "segments": seg_map}, f, ensure_ascii=False, indent=1)
    print(f"[{lang}] map scritta: {len(seg_map)} segmenti")
